SELECT name FROM instructor WHERE ID IN (
    SELECT s_id FROM advisor WHERE s_ID IN (
        SELECT i_id FROM student ORDER BY tot_cred DESC LIMIT 1)
    )
)

SELECT employee_id FROM employees WHERE department_id NOT IN (
    SELECT department_id FROM departments WHERE manager_id BETWEEN 100 AND 200
)

SELECT Name, Country FROM artist WHERE Artist_ID IN (
    SELECT Artist_ID FROM exhibition_record GROUP BY Artist_ID ORDER BY count(*) DESC LIMIT 1
)
